      "schopenhauerBioText": "Born in Danzig in 1788, Schopenhauer was one of the greatest 19th-century thinkers and a pioneer in exploring the depths of the human psyche. He distinguished himself through literary clarity and an uncompromising analysis of will and desires.",
      "schopenhauerThoughtList": "<li><strong>The Will to Live:</strong> The universal force driving all beings, generating continuous desires and suffering.</li><li><strong>The Illusion of Happiness:</strong> True happiness is negative (the absence of pain), and peace lies in detachment and tranquility.</li><li><strong>Art & Compassion:</strong> Two sovereign paths to transcend egoism and soothe the human mind.</li>",
