      "worksHeading": "أهم مؤلفاته",
      "schopenhauerBioText": "ولد في دانتزيغ عام 1788، ويعد من أعظم فلاسفة القرن التاسع عشر ورائد سبر أغوار النفس البشرية قبل فرويد ونيتشه. تميز بأسلوبه الأدبي الساحر وصراحته المتناهية في تشريح رغبات الإنسان ومصادر معاناته.",
      "schopenhauerThoughtList": "<li><strong>إرادة الحياة (La Volonté) :</strong> القوة الكونية الدافعة لكل الكائنات والتي تولد الرغبة والصراع المستمر.</li><li><strong>وهم السعادة :</strong> السعادة الحقيقية سلبية (غياب الألم)، والهدوء النفسي يكمن في الاكتفاء والسكينة.</li><li><strong>الشفقة والفن (L'Art & La Compassion) :</strong> هما الملاذ الإنساني للتحرر من قيود الأنانية والألم.</li>",
      "discoverPhilosophy": "اكتشف فكره الكامل",
